    if pa.types.is_fixed_size_list(chunk.type):
        chunk = chunk.cast(pa.list_(chunk.type.value_type))
    indices = pc.add(chunk.offsets[1:], key)
    if chunk.null_count:
        indices = pc.if_else(chunk.is_valid(), indices, None)
